function showReview(title,data,apply){const d=document.querySelector('#modal');d.innerHTML='<div class="modal-head"><h2>'+title+'</h2><button type="button" data-close class="icon-button">×</button></div><pre class="admin-json">'+escapeHtml(JSON.stringify(redact(data),null,2))+'</pre><div class="modal-actions"><button type="button" data-close class="secondary">Hủy</button><button type="button" id="applyReview" class="primary">Áp dụng</button></div>';d.showModal();d.querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>d.close());applyReview.onclick=async()=>{applyReview.disabled=true;try{await apply();d.close();toast('Đã áp dụng');load()}catch(e){toast(e.message,true);applyReview.disabled=false}}}
