function renderPricing(d){const services=listOf(d,'services'),groups=listOf(d,'priceGroups'),history=listOf(d,'priceHistory');content.innerHTML='<div class="admin-tabs pricing-tabs"><button class="active" data-pricing-tab="overview">Tổng quan</button><button data-pricing-tab="alerts">Cảnh báo giá</button><button data-pricing-tab="history">Lịch sử thay đổi giá</button><button data-pricing-tab="review">Dịch vụ cần duyệt</button></div><div id="pricingPane"></div>';const serviceName=id=>services.find(s=>s.id===id)?.name||id;function overview(){pricingPane.innerHTML='<article class="admin-card"><h2>Cập nhật bảng giá</h2><p class="helper">Backend tính toán thập phân an toàn và xác nhận mọi mức giá.</p><button class="primary" data-action="preview">Xem trước thay đổi</button></article>'+resourceTable(services,[{key:'name',label:'Dịch vụ'},{key:'providerCost',label:'Giá vốn NCC',render:r=>money(r.providerCost)},{key:'rate',label:'Giá hiện tại',render:r=>money(r.rate)},{key:'priceReviewStatus',label:'Trạng thái kiểm tra giá',render:r=>status(r.priceReviewStatus,reviewLabel(r.priceReviewStatus))}]);bindActions(a=>{if(a==='preview')openForm('Xem trước mức giá',[{name:'serviceId',label:'Dịch vụ',type:'select',options:options(services),required:true},{name:'priceGroupId',label:'Cấp khách hàng',type:'select',options:groups.map(g=>({value:g.id,label:tierLabel(g.code)})),required:true},{name:'rate',label:'Mức giá',required:true}],{},async body=>{const preview=await api.post('/api/v1/admin/pricing/simple/preview',body);showReview('Kiểm tra thay đổi',preview,()=>api.post('/api/v1/admin/pricing/simple/apply',{...body,previewToken:preview.previewToken}))})})}function historyPane(){pricingPane.innerHTML=resourceTable(history,[{key:'serviceId',label:'Dịch vụ',render:r=>escapeHtml(serviceName(r.serviceId))},{key:'oldProviderCost',label:'Giá vốn cũ',render:r=>money(r.oldProviderCost)},{key:'newProviderCost',label:'Giá vốn mới',render:r=>money(r.newProviderCost)},{key:'oldSaleRate',label:'Giá bán cũ',render:r=>money(r.oldSaleRate)},{key:'newSaleRate',label:'Giá bán mới',render:r=>money(r.newSaleRate)},{key:'changePercent',label:'Thay đổi %'},{key:'reason',label:'Lý do'},{key:'source',label:'Nguồn'},{key:'createdAt',label:'Thời gian',render:r=>date(r.createdAt)}])}async function alertsPane(){pricingPane.innerHTML='<div class="admin-skeleton"></div>';try{const result=await api.get('/api/v1/admin/pricing/alerts'),rows=listOf(result);pricingPane.innerHTML=resourceTable(rows,[{key:'serviceId',label:'Dịch vụ',render:r=>escapeHtml(serviceName(r.serviceId))},{key:'type',label:'Loại'},{key:'severity',label:'Mức độ',render:r=>status(r.severity)},{key:'message',label:'Nội dung',className:'service-name'},{key:'status',label:'Trạng thái',render:r=>status(r.status)},{key:'createdAt',label:'Thời gian',render:r=>date(r.createdAt)}],r=>r.status==='OPEN'&&can('pricing.manage')?button('Đã xử lý','resolve-alert',r.id,'success'):'');bindActions((a,id)=>a==='resolve-alert'&&mutate('/api/v1/admin/pricing/alerts/'+id+'/resolve',{},'Xử lý cảnh báo'))}catch(e){pricingPane.innerHTML='<p class="error-text">'+escapeHtml(e.message)+'</p>'}}function show(tab){document.querySelectorAll('[data-pricing-tab]').forEach(x=>x.classList.toggle('active',x.dataset.pricingTab===tab));if(tab==='overview')overview();if(tab==='history')historyPane();if(tab==='alerts')alertsPane();if(tab==='review'){const rows=services.filter(s=>s.priceReviewStatus==='PRICE_REVIEW');pricingPane.innerHTML=resourceTable(rows,[{key:'name',label:'Dịch vụ'},{key:'providerCost',label:'Giá vốn NCC',render:r=>money(r.providerCost)},{key:'rate',label:'Giá bán',render:r=>money(r.rate)},{key:'priceReviewStatus',label:'Trạng thái',render:r=>status(r.priceReviewStatus,reviewLabel(r.priceReviewStatus))}])}}document.querySelectorAll('[data-pricing-tab]').forEach(x=>x.onclick=()=>show(x.dataset.pricingTab));show('overview')}

